"""Check the cloud constants the add-on computes (addon/src/cloud_constants.h, generated by
tools/gen_cloud_constants.py) against tools/patch_dxil.py's own evaluation of cloud_constant_lines, for settings
across their ranges, at their limits and off: builds and runs tools/lab/cloud_constants_test.cpp. Also checks the
header is up to date.

    python tools/test_cloud_constants.py
"""
import math
import random
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "tools"))
import build_addon  # noqa: E402
import patch_dxil as P  # noqa: E402


def settings() -> list[list[float]]:
    rng = random.Random(7)
    n = P.CLOUD_TUNABLES_SIZE // 4
    sets = [[0.0] * n, [1.0] * n, [-1.0] * n, [1000.0] * n]
    # the shipped defaults, and the user's
    for path in (ROOT / "shaders" / "tunables.defaults.ini", ROOT / "shaders" / "tunables.ini"):
        if path.exists():
            c = [0.0] * n
            for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
                parts = line.split("=")
                if len(parts) == 2 and parts[0].strip()[:1] == "C" and parts[0].strip()[1:].isdigit():
                    k = int(parts[0].strip()[1:])
                    if k < n:
                        c[k] = float(parts[1].split(";")[0])
            sets.append(c)
    for _ in range(400):
        sets.append([rng.choice([0.0, rng.uniform(-2, 2), rng.uniform(0, 50), rng.uniform(0, 20000),
                                 rng.uniform(-math.pi, math.pi)]) for _ in range(n)])
    return sets


def main():
    failures = []
    check = subprocess.run([sys.executable, str(ROOT / "tools" / "gen_cloud_constants.py"), "--check"],
                           capture_output=True, text=True)
    if check.returncode != 0:
        failures.append(check.stdout.strip() + check.stderr.strip())
    cmake = str(build_addon.find_cmake())
    build = ROOT / "build" / "lab-build"
    subprocess.run([cmake, "-S", str(ROOT / "tools" / "lab"), "-B", str(build)], check=True, stdout=subprocess.DEVNULL)
    subprocess.run([cmake, "--build", str(build), "--config", "Release", "--target", "cloud_constants_test"],
                   check=True, stdout=subprocess.DEVNULL)
    sets = settings()
    run = subprocess.run([str(ROOT / "build" / "lab" / "cloud_constants_test.exe")],
                         input="\n".join(" ".join(repr(float(v)) for v in c) for c in sets) + "\n",
                         capture_output=True, text=True, check=True)
    rows = [list(map(float, line.split())) for line in run.stdout.splitlines()]
    worst = 0.0
    for c, got in zip(sets, rows):
        env = P.eval_cloud_constants(c)
        for k, name in enumerate(P.CLOUD_CONSTANTS):
            want, have = float(env[name]), got[k]
            if math.isnan(want) and math.isnan(have) or want == have:
                continue
            if math.isinf(want) or math.isinf(have) or math.isnan(want) or math.isnan(have):
                failures.append(f"{name}: {have} != {want} for C = {c[:6]}...")
                continue
            # (the transcendental functions: the C runtime's against numpy's float32, within a few units)
            err = abs(have - want) / max(abs(want), 1e-6)
            worst = max(worst, err)
            if err > 1e-6:
                failures.append(f"{name}: {have} != {want} (rel. {err:.1e})")
    print(f"{len(sets)} settings x {len(P.CLOUD_CONSTANTS)} constants; worst rel. difference {worst:.1e}")
    for f in failures[:20]:
        print("FAIL", f)
    print("all passed" if not failures else f"{len(failures)} FAILED")
    sys.exit(1 if failures else 0)


if __name__ == "__main__":
    main()
